/*
 * Vaultlix avatar builder. Loaded on demand by openAvatarBuilder() in index.html, after
 * vendor/open-peeps.js (the CC0 Open Peeps parts, see that file's header).
 *
 * An avatar is a handful of choices (hairstyle, expression, skin, beard, glasses, colours), drawn on this
 * device by stacking SVG layers. Nothing is generated by a server, so it is instant, free and private.
 * Because it is parts and not a picture, the same person can be drawn with any expression: that is the
 * foundation for VaultMoji reactions.
 *
 * The drawing code is pure (no DOM) so it can be tested; the builder sheet is the only part that touches
 * the page.
 */
(function () {
  'use strict';

  const BACKGROUNDS = ['#F3E6EA', '#E3EEF7', '#E6F2E3', '#FFF1D6', '#EADFF5', '#FBE0D8', '#DDEFEF', '#EDE8E3'];
  const SELECTION_KEY_PREFIX = 'vaultlix_avatar_selection:';

  function parts() { return window.VaultlixPeeps; }

  function humanize(name) {
    const spaced = String(name).replace(/([a-z])([A-Z0-9])/g, '$1 $2').replace(/([0-9])([a-z])/gi, '$1 $2');
    return spaced.charAt(0).toUpperCase() + spaced.slice(1).toLowerCase();
  }

  function defaultSelection() {
    return { head:'short2', face:'smile', facialHair:null, accessories:null, skin:2, hair:0, clothing:5, background:0 };
  }

  const inRange = (count, value) => Number.isInteger(value) && value >= 0 && value < count;

  // Whatever is stored or suggested, only choices that exist come out; the rest fall back to the default.
  function normalizeSelection(value, P = parts()) {
    const base = defaultSelection();
    const source = value && typeof value === 'object' ? value : {};
    const pick = (group, key, allowNone) => {
      const candidate = source[key];
      if (allowNone && (candidate === null || candidate === undefined)) return null;
      return typeof candidate === 'string' && Object.prototype.hasOwnProperty.call(P[group], candidate) ? candidate : base[key];
    };
    return {
      head:pick('head', 'head', false),
      face:pick('face', 'face', false),
      facialHair:pick('facialHair', 'facialHair', true),
      accessories:pick('accessories', 'accessories', true),
      skin:inRange(P.colors.skin.length, source.skin) ? source.skin : base.skin,
      hair:inRange(P.colors.hair.length, source.hair) ? source.hair : base.hair,
      clothing:inRange(P.colors.clothing.length, source.clothing) ? source.clothing : base.clothing,
      background:inRange(BACKGROUNDS.length, source.background) ? source.background : base.background,
    };
  }

  function substitute(svg, colors) {
    return svg.split('@S@').join(colors.skin).split('@C@').join(colors.clothing).split('@H@').join(colors.hair);
  }

  // The avatar as an SVG string. `thumb` draws just the head (no shoulders, no background) for option tiles.
  function avatarSvg(selection, { size = 256, thumb = false, background = true } = {}, P = parts()) {
    const sel = normalizeSelection(selection, P);
    const colors = {
      skin:`#${P.colors.skin[sel.skin]}`, clothing:`#${P.colors.clothing[sel.clothing]}`, hair:`#${P.colors.hair[sel.hair]}`,
    };
    const layer = (group, name) => (name ? `<g transform="${P.layers[group]}">${substitute(P[group][name], colors)}</g>` : '');
    const viewBox = thumb ? '80 -20 540 540' : P.viewBox;
    const fill = !thumb && background ? `<rect width="704" height="704" fill="${BACKGROUNDS[sel.background]}"/>` : '';
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}" width="${size}" height="${size}" fill="none">`
      + fill
      + (thumb ? '' : substitute(P.torso, colors))
      + layer('head', sel.head) + layer('face', sel.face) + layer('facialHair', sel.facialHair) + layer('accessories', sel.accessories)
      + '</svg>';
  }

  function randomSelection(random = Math.random, P = parts()) {
    const choice = list => list[Math.floor(random() * list.length)];
    const withHairColour = random() < 0.5;
    const head = withHairColour ? choice(P.hairColoured) : choice(Object.keys(P.head));
    return normalizeSelection({
      head,
      face:choice(['smile', 'smileBig', 'calm', 'cute', 'smileTeethGap', 'serious']),
      facialHair:random() < 0.3 ? choice(Object.keys(P.facialHair)) : null,
      accessories:random() < 0.25 ? choice(Object.keys(P.accessories)) : null,
      skin:Math.floor(random() * P.colors.skin.length),
      hair:P.hairColoured.includes(head) ? Math.floor(random() * P.colors.hair.length) : 0,
      clothing:Math.floor(random() * P.colors.clothing.length),
      background:Math.floor(random() * BACKGROUNDS.length),
    }, P);
  }

  // A suggestion (from a photo) only replaces the features it names.
  function applySuggestion(selection, suggestion, P = parts()) {
    return normalizeSelection({ ...normalizeSelection(selection, P), ...(suggestion && typeof suggestion === 'object' ? suggestion : {}) }, P);
  }

  function svgToJpeg(svg, pixels = 512) {
    return new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => {
        try {
          const canvas = document.createElement('canvas');
          canvas.width = pixels; canvas.height = pixels;
          const context = canvas.getContext('2d', { alpha:false });
          context.drawImage(image, 0, 0, pixels, pixels);
          resolve(canvas.toDataURL('image/jpeg', 0.92));
        } catch (error) { reject(error); }
      };
      image.onerror = () => reject(new Error('Could not draw your avatar'));
      image.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
    });
  }

  // ── Builder sheet ──────────────────────────────────────────────────────────
  const CSS = `
  #avatar-builder-overlay{position:fixed;inset:0;z-index:10060;background:rgba(20,10,16,.6);display:flex;align-items:flex-end;justify-content:center}
  #avatar-builder-overlay .avb-sheet{width:min(100%,520px);max-height:94dvh;overflow:auto;background:#fff;border-radius:22px 22px 0 0;padding:16px 16px calc(18px + env(safe-area-inset-bottom));font-family:Inter,sans-serif;color:#271D25;-webkit-overflow-scrolling:touch}
  #avatar-builder-overlay .avb-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}
  #avatar-builder-overlay .avb-head strong{font:700 18px/1.2 Inter,sans-serif}
  #avatar-builder-overlay .avb-close{width:36px;height:36px;border:0;border-radius:50%;background:#F4E8ED;color:#682C43;font-size:20px;cursor:pointer}
  #avatar-builder-overlay .avb-preview{width:176px;height:176px;margin:4px auto 10px;border-radius:50%;overflow:hidden;box-shadow:0 8px 24px rgba(104,44,67,.18)}
  #avatar-builder-overlay .avb-preview svg{display:block;width:100%;height:100%}
  #avatar-builder-overlay .avb-tabs{display:flex;gap:6px;overflow-x:auto;padding:2px 0 8px;scrollbar-width:none}
  #avatar-builder-overlay .avb-tabs::-webkit-scrollbar{display:none}
  #avatar-builder-overlay .avb-tab{flex:none;border:1px solid #E9D9E0;background:#fff;color:#682C43;border-radius:999px;padding:7px 13px;font:650 13px Inter,sans-serif;cursor:pointer}
  #avatar-builder-overlay .avb-tab[aria-selected="true"]{background:#682C43;border-color:#682C43;color:#fff}
  #avatar-builder-overlay .avb-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(72px,1fr));gap:8px;max-height:30dvh;overflow:auto;padding:2px}
  #avatar-builder-overlay .avb-tile{border:2px solid transparent;border-radius:14px;background:#FBF4F6;padding:4px;cursor:pointer;font:600 10.5px Inter,sans-serif;color:#8A747C;display:flex;flex-direction:column;align-items:center;gap:2px}
  #avatar-builder-overlay .avb-tile svg{width:100%;height:auto;display:block}
  #avatar-builder-overlay .avb-tile[aria-pressed="true"]{border-color:#682C43}
  #avatar-builder-overlay .avb-none{min-height:60px;justify-content:center;font-size:12px}
  #avatar-builder-overlay .avb-swatches{display:flex;flex-wrap:wrap;gap:10px;padding:4px 2px}
  #avatar-builder-overlay .avb-swatch{width:38px;height:38px;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 1px #DCCDD2;cursor:pointer}
  #avatar-builder-overlay .avb-swatch[aria-pressed="true"]{box-shadow:0 0 0 3px #682C43}
  #avatar-builder-overlay .avb-note{margin:6px 2px 4px;font:500 12px/1.4 Inter,sans-serif;color:#8A747C}
  #avatar-builder-overlay .avb-actions{display:grid;gap:8px;margin-top:12px}
  #avatar-builder-overlay .avb-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}
  #avatar-builder-overlay .avb-btn{border:1px solid #DCCDD2;background:#fff;color:#682C43;border-radius:14px;padding:12px;font:650 14px Inter,sans-serif;cursor:pointer}
  #avatar-builder-overlay .avb-btn.primary{background:#682C43;border-color:#682C43;color:#fff}
  #avatar-builder-overlay .avb-btn:disabled{opacity:.55;cursor:default}
  #avatar-builder-overlay .avb-consent{display:flex;gap:8px;align-items:flex-start;font:500 12px/1.4 Inter,sans-serif;color:#6D5A63;margin-top:10px}
  #avatar-builder-overlay .avb-link{border:0;background:none;color:#8A747C;text-decoration:underline;font:500 12.5px Inter,sans-serif;cursor:pointer;padding:6px}
  #avatar-builder-overlay .avb-status{min-height:18px;margin-top:8px;text-align:center;font:600 12.5px/1.4 Inter,sans-serif;color:#682C43}`;

  function builderTabs(P) {
    return [
      { id:'hair', label:'Hair', kind:'parts', group:'head', key:'head' },
      { id:'hairColour', label:'Hair colour', kind:'hairColour' },
      { id:'face', label:'Expression', kind:'parts', group:'face', key:'face' },
      { id:'skin', label:'Skin', kind:'swatch', key:'skin', colors:P.colors.skin.map(hex => `#${hex}`) },
      { id:'beard', label:'Beard', kind:'parts', group:'facialHair', key:'facialHair', none:'No beard' },
      { id:'glasses', label:'Glasses', kind:'parts', group:'accessories', key:'accessories', none:'None' },
      { id:'top', label:'Top', kind:'swatch', key:'clothing', colors:P.colors.clothing.map(hex => `#${hex}`) },
      { id:'background', label:'Background', kind:'swatch', key:'background', colors:BACKGROUNDS },
    ];
  }

  function open() {
    const P = parts();
    if (!P) { toast('Could not open the avatar builder.'); return; }
    const state = loadAccountState();
    if (!state) { openAccountPanel(); return; }
    document.getElementById('avatar-builder-overlay')?.remove();
    if (!document.getElementById('avatar-builder-style')) {
      const style = document.createElement('style');
      style.id = 'avatar-builder-style';
      style.textContent = CSS;
      document.head.appendChild(style);
    }
    const storageKey = SELECTION_KEY_PREFIX + state.accountId;
    let selection = defaultSelection();
    try { selection = normalizeSelection(JSON.parse(localStorage.getItem(storageKey) || 'null'), P); } catch (error) {}
    const tabs = builderTabs(P);
    let activeTab = 'hair';
    let busy = false;

    const overlay = document.createElement('div');
    overlay.id = 'avatar-builder-overlay';
    overlay.innerHTML = `<div class="avb-sheet" role="dialog" aria-modal="true" aria-label="Build your avatar">
      <div class="avb-head"><strong>Your avatar</strong><button type="button" class="avb-close" data-avb="close" aria-label="Close">×</button></div>
      <div class="avb-preview" id="avb-preview"></div>
      <div class="avb-tabs" role="tablist">${tabs.map(tab => `<button type="button" role="tab" class="avb-tab" data-tab="${tab.id}">${tab.label}</button>`).join('')}</div>
      <div id="avb-options"></div>
      <div class="avb-actions">
        <div class="avb-row"><button type="button" class="avb-btn" data-avb="suggest">Suggest from a photo</button><button type="button" class="avb-btn" data-avb="random">Surprise me</button></div>
        <label class="avb-consent"><input type="checkbox" id="avb-consent"/><span>I agree to send the photo I pick to OpenAI to suggest features for my avatar. Vaultlix does not keep it, and you can change anything afterwards.</span></label>
        <button type="button" class="avb-btn primary" data-avb="save">Use as my profile picture</button>
        <button type="button" class="avb-link" data-avb="photo">Or make an AI cartoon from a photo instead</button>
      </div>
      <div class="avb-status" id="avb-status" role="status" aria-live="polite"></div>
      <input type="file" id="avb-file" accept="image/*,.heic,.heif" hidden/>
    </div>`;

    const $ = id => overlay.querySelector(`#${id}`);
    const setStatus = text => { $('avb-status').textContent = text || ''; };

    function renderPreview() { $('avb-preview').innerHTML = avatarSvg(selection, { size:176 }, P); }

    function tile(label, svg, pressed, attributes) {
      return `<button type="button" class="avb-tile" aria-pressed="${pressed}" ${attributes}>${svg}<span>${label}</span></button>`;
    }

    function renderOptions() {
      const tab = tabs.find(item => item.id === activeTab);
      overlay.querySelectorAll('.avb-tab').forEach(button => button.setAttribute('aria-selected', String(button.dataset.tab === activeTab)));
      const holder = $('avb-options');
      if (tab.kind === 'swatch') {
        holder.innerHTML = `<div class="avb-swatches">${tab.colors.map((color, index) =>
          `<button type="button" class="avb-swatch" style="background:${color}" aria-label="Colour ${index + 1}" aria-pressed="${selection[tab.key] === index}" data-key="${tab.key}" data-index="${index}"></button>`).join('')}</div>`;
        return;
      }
      if (tab.kind === 'hairColour') {
        const supported = P.hairColoured.includes(selection.head);
        holder.innerHTML = `<div class="avb-swatches">${P.colors.hair.map((hex, index) =>
          `<button type="button" class="avb-swatch" style="background:#${hex}" aria-label="Hair colour ${index + 1}" aria-pressed="${selection.hair === index}" data-key="hair" data-index="${index}"></button>`).join('')}</div>
          <div class="avb-note">${supported ? 'Pick a colour for this hairstyle.' : 'Most hairstyles are drawn in black. These styles take a colour:'}</div>
          <div class="avb-grid">${P.hairColoured.map(name =>
            tile(humanize(name), avatarSvg({ ...selection, head:name }, { size:80, thumb:true }, P), selection.head === name, `data-key="head" data-value="${name}"`)).join('')}</div>`;
        return;
      }
      const names = Object.keys(P[tab.group]);
      const none = tab.none
        ? `<button type="button" class="avb-tile avb-none" aria-pressed="${selection[tab.key] === null}" data-key="${tab.key}" data-value="">${tab.none}</button>` : '';
      holder.innerHTML = `<div class="avb-grid">${none}${names.map(name =>
        tile(humanize(name), avatarSvg({ ...selection, [tab.key]:name }, { size:80, thumb:true }, P), selection[tab.key] === name, `data-key="${tab.key}" data-value="${name}"`)).join('')}</div>`;
    }

    function refresh() { renderPreview(); renderOptions(); }

    async function suggestFromPhoto(file) {
      busy = true; setStatus('Reading your photo…');
      try {
        const prepared = await prepareDailyLookImage(file);
        const state = loadAccountState();
        const result = await api('/api/account/avatar-suggest', { accountId:state.accountId, sessionToken:state.sessionToken, image:prepared.image });
        if (result.error) { setStatus(result.error); return; }
        selection = applySuggestion(selection, result.suggestion, P);
        refresh();
        setStatus('Suggested from your photo. Change anything you like.');
      } catch (error) {
        setStatus(error?.message || 'Could not read that photo.');
      } finally { busy = false; $('avb-file').value = ''; }
    }

    async function save() {
      if (busy) return;
      busy = true; setStatus('Saving your avatar…');
      overlay.querySelector('[data-avb="save"]').disabled = true;
      try {
        const jpeg = await svgToJpeg(avatarSvg(selection, { size:512 }, P), 512);
        if (await saveProfileImageUpdate('replace', jpeg)) {
          try { localStorage.setItem(storageKey, JSON.stringify(selection)); } catch (error) {}
          toast('Avatar added to your profile');
          overlay.remove();
          return;
        }
        setStatus('Your avatar was not saved. Please try again.');
      } catch (error) {
        setStatus(error?.message || 'Could not save your avatar.');
      } finally {
        busy = false;
        const button = overlay.querySelector('[data-avb="save"]');
        if (button) button.disabled = false;
      }
    }

    overlay.addEventListener('click', event => {
      if (event.target === overlay) { overlay.remove(); return; }
      const target = event.target.closest?.('button');
      if (!target) return;
      if (target.dataset.tab) { activeTab = target.dataset.tab; renderOptions(); return; }
      if (target.dataset.key) {
        const key = target.dataset.key;
        if (target.dataset.index !== undefined) selection[key] = Number(target.dataset.index);
        else selection[key] = target.dataset.value === '' ? null : target.dataset.value;
        refresh();
        return;
      }
      const action = target.dataset.avb;
      if (action === 'close') overlay.remove();
      else if (action === 'random') { selection = randomSelection(Math.random, P); refresh(); setStatus(''); }
      else if (action === 'save') save();
      else if (action === 'photo') { overlay.remove(); openAvatarFromPhoto(); }
      else if (action === 'suggest') {
        if (busy) return;
        if (!$('avb-consent').checked) { setStatus('Please tick the permission box first.'); return; }
        $('avb-file').click();
      }
    });
    $('avb-file').addEventListener('change', event => {
      const file = event.target.files?.[0];
      if (file) suggestFromPhoto(file);
    });

    document.body.appendChild(overlay);
    refresh();
  }

  // Not called `api`: the sheet above calls the page's own api() to reach the server.
  const exported = {
    BACKGROUNDS, SELECTION_KEY_PREFIX, defaultSelection, normalizeSelection, avatarSvg, randomSelection, applySuggestion, humanize, svgToJpeg, open,
  };
  if (typeof window !== 'undefined') window.VaultlixAvatar = exported;
  if (typeof module !== 'undefined' && module.exports) module.exports = exported;
}());
